#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
 BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
 BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
 BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=() # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=() # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
 [[ -t 1 ]] || return 0
 if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
 _clear
 printf '\n%s%s %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
 printf '%s %s stages · about %s minutes%s\n\n' \
 "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
 printf '%s You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
 printf ' captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
 printf ' later — it remembers values already saved.%s\n' "$RESET"
 pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
 _clear
 _STAGE_INDEX=$((_STAGE_INDEX + 1))
 local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
 (( remaining < 0 )) && remaining=0
 _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
 printf '\n%s%s▸ Stage %s/%s · %s%s %s(~%s min left)%s\n' \
 "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say() { printf ' %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf ' %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf ' %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf ' %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
 local url="$1"
 printf ' %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
 { if command -v wslview >/dev/null 2>&1; then wslview "$url"
 elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
 elif command -v xdg-open >/dev/null 2>&1; then xdg-open "$url"
 elif command -v open >/dev/null 2>&1; then open "$url"
 else warn "couldn't open a browser — visit it manually: $url"; fi
 } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
 printf ' %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
 read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
 local reply=""
 printf ' %s? %s [y/N] ' "$YELLOW" "$1"
 read -r reply || true
 [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
 [[ -f "$ENV_FILE" ]] || return 1
 local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
 printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
 local key="$1" prompt="$2" current input
 current=$(_existing "$key" || true)
 if [[ -n "$current" ]]; then
 printf ' %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
 else
 printf ' %s%s%s ' "$BOLD" "$prompt" "$RESET"
 fi
 read -r input || true
 [[ -z "$input" && -n "$current" ]] && input="$current"
 printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
 local key="$1" prompt="$2" current input
 current=$(_existing "$key" || true)
 if [[ -n "$current" ]]; then
 printf ' %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
 else
 printf ' %s%s%s ' "$BOLD" "$prompt" "$RESET"
 fi
 read -rs input || true
 printf '\n'
 [[ -z "$input" && -n "$current" ]] && input="$current"
 printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
 local key="$1" value="$2" tmp
 touch "$ENV_FILE"
 tmp=$(mktemp)
 grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
 printf '%s=%s\n' "$key" "$value" >> "$tmp"
 mv "$tmp" "$ENV_FILE"
 WRITTEN_ENV+=("$key")
 printf ' %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
 local name="$1" value="$2"
 if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
 if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
 WRITTEN_SECRET+=("$name")
 printf ' %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
 return
 fi
 fi
 SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
 warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
 local name="$1" value="$2"
 if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
 if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
 printf ' %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
 return
 fi
 fi
 SKIPPED+=("GitHub variable $name")
 warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
 _clear
 printf '\n%s%s ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
 (( ${#WRITTEN_ENV[@]} )) && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
 (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
 if (( ${#SKIPPED[@]} )); then
 printf '\n'; warn "still to do by hand:"
 for s in "${SKIPPED[@]}"; do note " - $s"; done
 fi
 printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

# The project IDs are public values; they go in a file of their own so that
# Claude (which never reads .env files) can read them for `flutterfire configure`.
ENV_FILE="${FIREBASE_PROJECTS_FILE:-tool/firebase-projects.env}"
mkdir -p "$(dirname "$ENV_FILE")"

TOTAL_STAGES=9
TOTAL_MINUTES=25

DEV_NAME="hold-my-dice-dev"
PROD_NAME="hold-my-dice"
REGION="asia-southeast1"
SITE_DOMAIN="hold-my-dice.pages.dev"
CONSOLE="https://console.firebase.google.com"

# Reads a project ID from the human and refuses anything that cannot be one.
ask_project_id() {
  local key="$1" prompt="$2"
  while true; do
    ask "$key" "$prompt"
    if [[ "${!key}" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]]; then return; fi
    warn "that does not look like a project ID (lower case letters, digits and dashes). Try again."
  done
}

# Looks for the Firestore region in the CLI's list of databases of a project.
firestore_region() {
  firebase firestore:databases:list --project "$1" 2>/dev/null | grep -o "$REGION" | head -n1 || true
}

# Checks the database of a project is where it should be; offers to retry.
check_firestore() {
  local project="$1"
  while true; do
    if [[ -n "$(firestore_region "$project")" ]]; then
      printf ' %s✓ found a Firestore database in %s%s\n' "$GREEN" "$REGION" "$RESET"
      return
    fi
    warn "no Firestore database in $REGION found for $project yet."
    note "(the region cannot be changed afterwards: if it was created somewhere else, delete it in the console and create it again)"
    if confirm "Check again?"; then continue; fi
    SKIPPED+=("Firestore database in $REGION for $project was not confirmed")
    return
  done
}

banner "Firebase — dev and prod projects for Hold My Dice"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Firebase CLI sign-in" 3
if ! command -v firebase >/dev/null 2>&1; then
  warn "the Firebase CLI is not installed."
  say "Install it in another terminal, then come back:"
  step "npm install -g firebase-tools"
  pause "Installed? Press Enter."
fi
if firebase login:list 2>/dev/null | grep -q "@"; then
  say "The CLI is already signed in:"
  firebase login:list 2>/dev/null | sed 's/^/   /'
  if confirm "Use a different Google account?"; then firebase login --reauth; fi
else
  say "A browser window opens; sign in with the Google account that owns the projects."
  firebase login
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Dev project — create it" 3
say "The dev project is for testing; the free quota is counted per project."
open_url "$CONSOLE/"
step "Click 'Create a project' (or 'Add project')."
step "Name it: $DEV_NAME"
step "Turn Google Analytics OFF (not needed), then click 'Create project'."
step "When it is ready, click the gear next to 'Project Overview' → Project settings."
step "Copy the 'Project ID' from the General tab (it can differ from the name)."
ask_project_id DEV_PROJECT_ID "Paste the dev Project ID:"
write_env DEV_PROJECT_ID "$DEV_PROJECT_ID"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Dev project — Firestore database" 3
say "This is the database the app writes rooms to."
open_url "$CONSOLE/project/$DEV_PROJECT_ID/firestore"
step "Click 'Create database'."
step "Location: pick $REGION (Singapore). This cannot be changed later."
step "Security rules: choose 'Start in production mode' (closed; Claude deploys the real rules)."
step "Click 'Create' and wait until the empty database page appears."
pause "Created? Press Enter and the wizard will check it."
check_firestore "$DEV_PROJECT_ID"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Dev project — anonymous sign-in" 2
say "Players sign in without an account; each phone gets its own anonymous ID."
open_url "$CONSOLE/project/$DEV_PROJECT_ID/authentication/providers"
step "If you see 'Get started', click it."
step "Under 'Sign-in method' choose 'Anonymous', switch it to Enabled, click Save."
note "(Google sign-in is for the admin page, which comes later; skip it for now.)"
pause "Anonymous is enabled? Press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Prod project — create it" 3
say "The prod project is the one the public site (and your friends) will use."
open_url "$CONSOLE/"
step "Click 'Add project'."
step "Name it: $PROD_NAME (if the ID is taken Firebase adds digits; that is fine)."
step "Turn Google Analytics OFF, then click 'Create project'."
step "Gear → Project settings → General → copy the 'Project ID'."
while true; do
  ask_project_id PROD_PROJECT_ID "Paste the prod Project ID:"
  [[ "$PROD_PROJECT_ID" != "$DEV_PROJECT_ID" ]] && break
  warn "that is the dev project. The prod project must be a different one."
done
write_env PROD_PROJECT_ID "$PROD_PROJECT_ID"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Prod project — Firestore database" 3
open_url "$CONSOLE/project/$PROD_PROJECT_ID/firestore"
step "Click 'Create database'."
step "Location: $REGION (Singapore) — the same as dev, and it cannot be changed later."
step "Security rules: 'Start in production mode'."
step "Click 'Create' and wait for the empty database page."
pause "Created? Press Enter and the wizard will check it."
check_firestore "$PROD_PROJECT_ID"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Prod project — anonymous sign-in" 2
open_url "$CONSOLE/project/$PROD_PROJECT_ID/authentication/providers"
step "If you see 'Get started', click it."
step "Sign-in method → Anonymous → Enabled → Save."
pause "Anonymous is enabled? Press Enter."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Prod project — allow the public site" 2
say "Without this, sign-in from $SITE_DOMAIN is refused."
open_url "$CONSOLE/project/$PROD_PROJECT_ID/authentication/settings"
step "Open the 'Authorized domains' section."
step "Click 'Add domain' and enter: $SITE_DOMAIN"
step "Click 'Add'. ('localhost' is already in the list; leave it.)"
pause "$SITE_DOMAIN is in the list? Press Enter."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Check both projects from the CLI" 4
say "Asking Firebase which projects this account can reach..."
projects="$(firebase projects:list 2>/dev/null || true)"
for p in "$DEV_PROJECT_ID" "$PROD_PROJECT_ID"; do
  if grep -q "$p" <<<"$projects"; then
    printf ' %s✓ %s is reachable from the CLI%s\n' "$GREEN" "$p" "$RESET"
  else
    warn "$p is not in 'firebase projects:list'. Is the CLI signed in with the account that created it?"
    SKIPPED+=("CLI cannot see project $p (run: firebase login)")
  fi
done
write_env FIREBASE_REGION "$REGION"
write_env FIREBASE_AUTHORIZED_DOMAIN "$SITE_DOMAIN"
note "Nothing secret was collected: these are public project IDs. Tell Claude the wizard is done and it will run 'flutterfire configure' for both projects."

finish
